function parseAuthorizationInput(input) {
    const value = input.trim();
    if (!value)
        return {};
    try {
        const url = new URL(value);
        return {
            code: url.searchParams.get("code") ?? undefined,
            state: url.searchParams.get("state") ?? undefined,
        };
    }
    catch {
        // not a URL
    }
    if (value.includes("#")) {
        const [code, state] = value.split("#", 2);
        return { code, state };
    }
    if (value.includes("code=")) {
        const params = new URLSearchParams(value);
        return {
            code: params.get("code") ?? undefined,
            state: params.get("state") ?? undefined,
        };
    }
    return { code: value };
}

function formatErrorDetails(error) {
    if (error instanceof Error) {
        const details = [`${error.name}: ${error.message}`];
        const errorWithCode = error;
        if (errorWithCode.code)
            details.push(`code=${errorWithCode.code}`);
        if (typeof errorWithCode.errno !== "undefined")
            details.push(`errno=${String(errorWithCode.errno)}`);
        if (typeof error.cause !== "undefined") {
            details.push(`cause=${formatErrorDetails(error.cause)}`);
        }
        if (error.stack) {
            details.push(`stack=${error.stack}`);
        }
        return details.join("; ");
    }
    return String(error);
}

async function postJson(url, body, signal) {
    const response = await fetch(url, {
        method: "POST",
        headers: {
            "Content-Type": "application/json",
            Accept: "application/json",
        },
        body: JSON.stringify(body),
        signal: AbortSignal.any([signal, AbortSignal.timeout(30_000)]),
    });
    const responseBody = await response.text();
    if (!response.ok) {
        throw new Error(`HTTP request failed. status=${response.status}; url=${url}; body=${responseBody}`);
    }
    return responseBody;
}

async function exchangeAuthorizationCode(code, state, verifier, redirectUri, signal) {
    let responseBody;
    try {
        responseBody = await postJson(TOKEN_URL, {
            grant_type: "authorization_code",
            client_id: CLIENT_ID,
            code,
            state,
            redirect_uri: redirectUri,
            code_verifier: verifier,
        }, signal);
    }
    catch (error) {
        throw new Error(`Token exchange request failed. url=${TOKEN_URL}; redirect_uri=${redirectUri}; response_type=authorization_code; details=${formatErrorDetails(error)}`);
    }
    let tokenData;
    try {
        tokenData = JSON.parse(responseBody);
    }
    catch (error) {
        throw new Error(`Token exchange returned invalid JSON. url=${TOKEN_URL}; body=${responseBody}; details=${formatErrorDetails(error)}`);
    }
    return {
        type: "oauth",
        refresh: tokenData.refresh_token,
        access: tokenData.access_token,
        expires: Date.now() + tokenData.expires_in * 1000 - 5 * 60 * 1000,
    };
}

async function loginAnthropic(interaction) {
    const { verifier, challenge } = await generatePKCE();
    const startCallbackServer = (port) => startOAuthCallbackServer({
        providerName: "Anthropic",
        host: CALLBACK_HOST,
        port,
        path: CALLBACK_PATH,
        redirectHost: "localhost",
        state: verifier,
        complete: async (code) => code,
        signal: interaction.signal,
    });
    // Without a callback server, login continues with the pasted redirect URL.
    const callback = await startCallbackServer(CALLBACK_PORT)
        .catch(() => startCallbackServer(0))
        .catch(() => undefined);
    const redirectUri = callback?.redirectUri ?? REDIRECT_URI;
    try {
        const authParams = new URLSearchParams({
            code: "true",
            client_id: CLIENT_ID,
            response_type: "code",
            redirect_uri: redirectUri,
            scope: SCOPES,
            code_challenge: challenge,
            code_challenge_method: "S256",
            state: verifier,
        });
        interaction.notify({
            type: "auth_url",
            url: `${AUTHORIZE_URL}?${authParams.toString()}`,
            instructions: "Complete login in your browser. If the browser is on another machine, paste the final redirect URL here.",
        });
        const result = await waitForCallbackOrManualInput(interaction, callback, {
            message: "Complete login in your browser, or paste the authorization code / redirect URL here:",
            placeholder: redirectUri,
        });
        let code;
        let state = verifier;
        if (result.type === "callback") {
            code = result.value;
        }
        else {
            const parsed = parseAuthorizationInput(result.input);
            if (parsed.state && parsed.state !== verifier)
                throw new Error("OAuth state mismatch");
            code = parsed.code;
            state = parsed.state ?? verifier;
        }
        if (!code)
            throw new Error("Missing authorization code");
        interaction.notify({ type: "progress", message: "Exchanging authorization code for tokens..." });
        return await exchangeAuthorizationCode(code, state, verifier, redirectUri, interaction.signal);
    }
    finally {
        callback?.close();
    }
}

async function loginAnthropicCopyCode(interaction) {
    const { verifier, challenge } = await generatePKCE();
    const authParams = new URLSearchParams({
        code: "true",
        client_id: CLIENT_ID,
        response_type: "code",
        redirect_uri: COPY_CODE_REDIRECT_URI,
        scope: SCOPES,
        code_challenge: challenge,
        code_challenge_method: "S256",
        state: verifier,
    });
    interaction.notify({
        type: "auth_url",
        url: `${AUTHORIZE_URL}?${authParams.toString()}`,
        instructions: "Complete login in your browser, then copy the code Anthropic shows and paste it here.",
    });
    const input = await interaction.prompt({
        type: "manual_code",
        message: "Paste the code Anthropic shows after you sign in:",
        placeholder: "code#state",
        signal: interaction.signal,
    });
    const parsed = parseAuthorizationInput(input);
    if (parsed.state && parsed.state !== verifier)
        throw new Error("OAuth state mismatch");
    if (!parsed.code)
        throw new Error("Missing authorization code");
    interaction.notify({ type: "progress", message: "Exchanging authorization code for tokens..." });
    return await exchangeAuthorizationCode(parsed.code, parsed.state ?? verifier, verifier, COPY_CODE_REDIRECT_URI, interaction.signal);
}

async function refreshAnthropicToken(refreshToken, signal) {
    let responseBody;
    try {
        responseBody = await postJson(TOKEN_URL, {
            grant_type: "refresh_token",
            client_id: CLIENT_ID,
            refresh_token: refreshToken,
        }, signal);
    }
    catch (error) {
        throw new Error(`Anthropic token refresh request failed. url=${TOKEN_URL}; details=${formatErrorDetails(error)}`);
    }
    let data;
    try {
        data = JSON.parse(responseBody);
    }
    catch (error) {
        throw new Error(`Anthropic token refresh returned invalid JSON. url=${TOKEN_URL}; body=${responseBody}; details=${formatErrorDetails(error)}`);
    }
    return {
        type: "oauth",
        refresh: data.refresh_token,
        access: data.access_token,
        expires: Date.now() + data.expires_in * 1000 - 5 * 60 * 1000,
    };
}

async login(interaction) {
        const method = await interaction.prompt({
            type: "select",
            message: "Select Anthropic login method:",
            options: [
                { id: ANTHROPIC_BROWSER_LOGIN_METHOD, label: "Browser login (default)" },
                { id: ANTHROPIC_COPY_CODE_LOGIN_METHOD, label: "Copy code login (headless)" },
            ],
        });
        if (method === ANTHROPIC_COPY_CODE_LOGIN_METHOD) {
            return loginAnthropicCopyCode(interaction);
        }
        if (method !== ANTHROPIC_BROWSER_LOGIN_METHOD) {
            throw new Error(`Unknown Anthropic login method: ${method}`);
        }
        return loginAnthropic(interaction);
    }

async toAuth(credential) {
        return { apiKey: credential.access };
    }

function randomValue() {
    return randomBytes(32).toString("base64url");
}

function authorizationResultFromCallback(url, expectedState) {
    const code = url.searchParams.get("code");
    if (!code)
        throw new Error("Missing authorization code");
    const state = url.searchParams.get("state");
    if (!state)
        throw new Error("Missing OAuth state");
    if (state !== expectedState)
        throw new Error("OAuth state mismatch");
    const clientId = url.searchParams.get("client_id")?.trim();
    if (!clientId)
        throw new Error("OpenAI OAuth registration callback did not contain an issued client ID");
    return { code, clientId };
}

function authorizationResultFromManualInput(input, expectedState) {
    let url;
    try {
        url = new URL(input.trim());
    }
    catch {
        throw new Error("Paste the full callback URL from the browser");
    }
    const expected = new URL(REDIRECT_URI);
    if (url.origin !== expected.origin || url.pathname !== expected.pathname) {
        throw new Error(`The pasted callback URL must start with ${REDIRECT_URI}`);
    }
    const error = url.searchParams.get("error");
    if (error)
        throw new Error(`ChatGPT authorization failed: ${error}`);
    return authorizationResultFromCallback(url, expectedState);
}

function sendHtml(response, status, body) {
    response.writeHead(status, { "Content-Type": "text/html; charset=utf-8" });
    response.end(body);
}

function startCallbackServer(expectedState) {
    return new Promise((resolve, reject) => {
        let resolveResult;
        let rejectResult;
        const result = new Promise((resolveAuthorization, rejectAuthorization) => {
            resolveResult = resolveAuthorization;
            rejectResult = rejectAuthorization;
        });
        const server = createServer((request, response) => {
            try {
                const url = new URL(request.url || "", REDIRECT_URI);
                if (url.pathname !== CALLBACK_PATH) {
                    sendHtml(response, 404, oauthErrorHtml("Callback route not found."));
                    return;
                }
                const error = url.searchParams.get("error");
                if (error) {
                    sendHtml(response, 400, oauthErrorHtml("ChatGPT was not connected.", `Error: ${error}`));
                    rejectResult(new Error(`ChatGPT authorization failed: ${error}`));
                    return;
                }
                let authorizationResult;
                try {
                    authorizationResult = authorizationResultFromCallback(url, expectedState);
                }
                catch (error) {
                    const message = error instanceof Error ? error.message : "Invalid callback";
                    sendHtml(response, 400, oauthErrorHtml(message));
                    return;
                }
                sendHtml(response, 200, oauthSuccessHtml("ChatGPT authentication completed. You can close this window."));
                resolveResult(authorizationResult);
            }
            catch {
                sendHtml(response, 500, oauthErrorHtml("Internal error while processing the callback."));
            }
        });
        server.once("error", reject);
        server.listen(CALLBACK_PORT, CALLBACK_HOST, () => {
            server.removeListener("error", reject);
            server.on("error", rejectResult);
            resolve({ server, result });
        });
    });
}

async function requestToken(body, signal) {
    const response = await fetch(TOKEN_URL, {
        method: "POST",
        headers: {
            accept: "application/json",
            "content-type": "application/x-www-form-urlencoded",
        },
        body,
        signal,
    });
    if (!response.ok) {
        const responseBody = await response.text().catch(() => "");
        throw new Error(`OpenAI OAuth token request failed (${response.status}): ${responseBody || response.statusText}`);
    }
    const data = await response.json();
    if (typeof data !== "object" || data === null || Array.isArray(data)) {
        throw new Error("OpenAI OAuth token response must be an object");
    }
    return data;
}

function requireTokenString(value, field) {
    if (typeof value !== "string" || value.trim().length === 0) {
        throw new Error(`OpenAI OAuth token response has invalid ${field}`);
    }
    return value;
